"""Minimal, careful HTTP client for the order service.

- Refreshes the bearer token whenever the service rejects it.
- On rate limiting, sleeps exactly as long as the service asks (plus a small margin).
- Retries transient failures; never invents data.
- Logs every non-200 response (status, headers, body) to a JSONL file.
"""
import email.utils
import http.client
import json
import socket
import time
import urllib.error
import urllib.request
from collections import Counter

BASE = "http://localhost:8080"


class FatalError(Exception):
    pass


class Client:
    def __init__(self, log_path, margin=0.1, max_attempts=200):
        self.token = None
        self.log_f = open(log_path, "a")
        self.margin = margin
        self.max_attempts = max_attempts
        self.stats = Counter()
        self.waited = 0.0

    def log(self, **kw):
        kw["ts"] = time.time()
        self.log_f.write(json.dumps(kw) + "\n")
        self.log_f.flush()

    # ---- low level -------------------------------------------------------
    def _raw(self, method, path, auth):
        req = urllib.request.Request(BASE + path, method=method)
        if auth:
            req.add_header("Authorization", f"Bearer {self.token}")
        try:
            with urllib.request.urlopen(req, timeout=60) as resp:
                return resp.status, dict(resp.headers.items()), resp.read()
        except urllib.error.HTTPError as e:
            try:
                body = e.read()
            except Exception:  # noqa: BLE001
                body = b""
            return e.code, dict(e.headers.items()) if e.headers else {}, body

    @staticmethod
    def _retry_after(headers, body_obj):
        """Return seconds to wait as instructed by the service, or None."""
        for k, v in headers.items():
            if k.lower() == "retry-after":
                v = v.strip()
                try:
                    return float(v)
                except ValueError:
                    dt = email.utils.parsedate_to_datetime(v)
                    return max(0.0, dt.timestamp() - time.time())
        if isinstance(body_obj, dict):
            for k, v in body_obj.items():
                kl = k.lower()
                if "retry" in kl or "wait" in kl:
                    try:
                        val = float(v)
                    except (TypeError, ValueError):
                        continue
                    if kl.endswith("_ms") or "millis" in kl:
                        val /= 1000.0
                    return val
        return None

    def _sleep(self, secs, why):
        secs = max(0.0, secs)
        self.waited += secs
        self.stats[f"sleep:{why}"] += 1
        time.sleep(secs)

    # ---- token ------------------------------------------------------------
    def refresh_token(self):
        backoff = 0.5
        for attempt in range(1, self.max_attempts + 1):
            try:
                status, headers, body = self._raw("POST", "/token", auth=False)
            except (urllib.error.URLError, http.client.HTTPException,
                    ConnectionError, socket.timeout, TimeoutError) as e:
                self.stats["token:neterr"] += 1
                self.log(kind="neterr", path="/token", err=repr(e))
                self._sleep(backoff, "neterr")
                backoff = min(backoff * 2, 10)
                continue
            body_obj = _try_json(body)
            if status == 200 and isinstance(body_obj, dict) and isinstance(body_obj.get("token"), str):
                self.token = body_obj["token"]
                self.stats["token:new"] += 1
                self.log(kind="token", token=self.token)
                return self.token
            self.stats[f"token:{status}"] += 1
            self.log(kind="non200", path="/token", method="POST", status=status,
                     headers=headers, body=body.decode("utf-8", "replace")[:2000])
            ra = self._retry_after(headers, body_obj)
            if ra is not None:
                self._sleep(ra + self.margin, "retry_after")
            else:
                self._sleep(backoff, "backoff")
                backoff = min(backoff * 2, 10)
        raise FatalError("could not obtain a token")

    # ---- authenticated GET ------------------------------------------------
    def get(self, path, ok_statuses=(200,), validate=None):
        """GET an authenticated path. Returns (status, parsed_json).

        Retries until a response with a status in ok_statuses arrives (and,
        for 200, until `validate(obj)` is truthy if given).
        """
        if self.token is None:
            self.refresh_token()
        backoff = 0.5
        for attempt in range(1, self.max_attempts + 1):
            self.stats["req"] += 1
            try:
                status, headers, body = self._raw("GET", path, auth=True)
            except (urllib.error.URLError, http.client.HTTPException,
                    ConnectionError, socket.timeout, TimeoutError) as e:
                self.stats["neterr"] += 1
                self.log(kind="neterr", path=path, err=repr(e))
                self._sleep(backoff, "neterr")
                backoff = min(backoff * 2, 10)
                continue
            body_obj = _try_json(body)
            if status in ok_statuses:
                if status == 200:
                    if body_obj is None or (validate is not None and not validate(body_obj)):
                        self.stats["bad200"] += 1
                        self.log(kind="bad200", path=path, headers=headers,
                                 body=body.decode("utf-8", "replace")[:4000])
                        self._sleep(backoff, "bad200")
                        backoff = min(backoff * 2, 10)
                        continue
                self.stats[f"ok:{status}"] += 1
                return status, body_obj
            self.stats[f"status:{status}"] += 1
            self.log(kind="non200", path=path, status=status, headers=headers,
                     token=self.token, body=body.decode("utf-8", "replace")[:2000])
            if status in (401, 403):
                self.refresh_token()
                continue
            ra = self._retry_after(headers, body_obj)
            if ra is not None:
                self._sleep(ra + self.margin, "retry_after")
            else:
                self._sleep(backoff, "backoff")
                backoff = min(backoff * 2, 10)
        raise FatalError(f"giving up on {path}")


def _try_json(body):
    try:
        return json.loads(body.decode("utf-8"))
    except Exception:  # noqa: BLE001
        return None

